<?php namespace AISEO\Chat; class Chat_Bot { public function init() { add_action('wp_ajax_ai_chat',[$this,'respond']); add_action('wp_ajax_nopriv_ai_chat',[$this,'respond']); add_action('wp_footer',[$this,'render_widget']); } public function respond() { check_ajax_referer('ai_chat_nonce','nonce'); $msg=sanitize_textarea_field($_POST['msg']??''); $pid=intval($_POST['pid']??0); $ctx=$pid?get_the_title($pid):'general'; wp_send_json_success(['reply'=>'AI reply: '.esc_html($msg).' (context: '.esc_html($ctx).')']); } public function render_widget() { if(is_admin())return; ?>
<div id="ai-chat-widget" style="position:fixed;bottom:24px;left:24px;z-index:9999;font-family:sans-serif;">
<button onclick="document.getElementById('chat-box').style.display=document.getElementById('chat-box').style.display==='none'?'block':'none';" style="border-radius:50%;width:56px;height:56px;border:none;background:linear-gradient(135deg,#e94560,#302b63);color:#fff;font-size:24px;box-shadow:0 6px 20px rgba(0,0,0,.3);cursor:pointer;">💬</button>
<div id="chat-box" style="display:none;width:340px;background:#fff;border-radius:16px;box-shadow:0 12px 40px rgba(0,0,0,.25);padding:16px;margin-bottom:12px;">
<div id="chat-log" style="max-height:260px;overflow-y:auto;font-size:.85rem;color:#222;line-height:1.5;"></div>
<input id="chat-in" onkeydown="if(event.key==='Enter')sendChat()" placeholder="Ask / بپرس..." style="width:100%;padding:8px;border-radius:8px;border:1px solid #ddd;margin-top:8px;"/>
</div></div>
<script>function sendChat(){const i=document.getElementById('chat-in'),log=document.getElementById('chat-log'),msg=i.value.trim();if(!msg)return;log.innerHTML+='<div style="margin:6px 2px;">🧑 '+msg+'</div>';i.value='';jQuery.post("<?php echo admin_url('admin-ajax.php'); ?>",{action:"ai_chat",nonce:"<?php echo wp_create_nonce('ai_chat_nonce'); ?>",msg:msg,pid:<?php echo get_the_ID()?:0; ?>},function(r){log.innerHTML+='<div style="margin:6px 2px;color:#302b63;">🤖 '+(r.data?.reply||'...')+'</div>';});}</script><?php } }
